.notification-tm,
.notification-modal {
    background-color: #060606;
    color: #e0e0e0;
    border-radius: 10px;
    padding: 10px;
    max-width: 600px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, .5);
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 1001;
    display: none;
    text-align: left;
    overflow: hidden
}

.modal-body {
    max-height: 350px !important;
    overflow: auto !important
}

.modal-header {
    padding: 15px;
    border-bottom: 1px solid #3d3d3d !important
}

.modal-header {
    align-items: center;
    position: relative
}

.modal-header h4 {
    margin: 0;
    font-size: 1.9em;
    color: #1269cf;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, .5);
    font-weight: 700;
    text-align: center;
    font-family: 'DVN-Notch', serif
}

.notification-info {
    font-style: italic !important;
    margin-top: 10px !important;
    color: #f0a500 !important;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, .5) !important
}

.close-modal {
    display: none
}

.notification-tm p,
.notification-modal p {
    color: #fff;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, .5);
    margin: 10px 0;
    text-align: left
}

.sender-info {
    font-style: italic;
    text-align: right;
    margin-top: 10px;
    color: #ff8a00;
    text-align: right
}

.mark-as-read {
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #28a745;
    border-color: #28a745;
    color: #fff;
    border-radius: 20px;
    padding: 5px 10px;
    text-align: center;
    cursor: pointer;
    margin-top: 20px;
    margin-left: auto;
    margin-right: auto;
    width: fit-content;
    box-shadow: 0 4px 15px rgba(0, 0, 0, .3);
    font-size: .9em
}

.mark-as-read i {
    margin-right: 5px;
    font-size: 1.2em
}

.mark-as-read:hover {
    background-color: #218838;
    border-color: #1e7e34
}

.prev-notification,
.next-notification {
    position: absolute;
    bottom: 0;
    background-color: rgba(0, 0, 0, .5);
    color: #1269cf;
    border: none;
    padding: 10px;
    cursor: pointer;
    font-size: 2.6em;
    z-index: 1002
}

.prev-notification {
    left: 10px
}

.next-notification {
    right: 10px
}

@media (max-width:600px) {
    .notification-tm,
    .notification-modal,
    .notification-summary {
        width: 90%;
        top: 5%;
        left: 50%;
        transform: translate(-50%, 0)
    }
}

#custom-login-modal {
    --cl-void: #060810;
    --cl-deep: #0a0e18;
    --cl-bronze: #3d2e1a;
    --cl-bronze-lit: #6b4d28;
    --cl-gold: #e8c878;
    --cl-gold-dim: #a88438;
    --cl-gold-bright: #ffe4a0;
    --cl-text: #e8e4dc;
    --cl-muted: #9a9aaa;
    --cl-cyan: #5ec8e8;
    --cl-success: #6ec9a0;
    --cl-danger: #e07070;
    --cl-info: #8ec8e8;
    position: fixed;
    inset: 0;
    z-index: 100050;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: max(16px, env(safe-area-inset-top)) 16px max(16px, env(safe-area-inset-bottom));
    visibility: hidden;
    opacity: 0;
    transition: opacity .3s ease, visibility 0s linear .3s
}

#custom-login-modal.active {
    visibility: visible;
    opacity: 1;
    transition: opacity .3s ease, visibility 0s
}

.custom-login-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(4, 6, 12, .82);
    backdrop-filter: blur(6px) saturate(.9);
    -webkit-backdrop-filter: blur(6px) saturate(.9)
}

.custom-login-content {
    position: relative;
    z-index: 1;
    width: min(100%, 400px);
    max-height: min(92vh, 680px);
    overflow-y: auto;
    padding: 26px 24px 22px;
    border-radius: 14px;
    background: linear-gradient(165deg, rgba(22, 18, 12, .96) 0%, rgba(8, 10, 18, .98) 100%);
    border: 1px solid rgba(232, 200, 120, .32);
    box-shadow: 0 20px 56px rgba(0, 0, 0, .65), 0 0 40px rgba(168, 132, 56, .08), inset 0 1px 0 rgba(255, 228, 160, .06);
    text-align: center;
    transform: translateY(10px);
    opacity: 0;
    transition: transform .35s cubic-bezier(.22, 1, .36, 1), opacity .3s ease
}

#custom-login-modal.active .custom-login-content {
    transform: translateY(0);
    opacity: 1
}

.custom-login-content:before {
    content: '';
    position: absolute;
    top: 0;
    left: 12%;
    right: 12%;
    height: 2px;
    border-radius: 0 0 2px 2px;
    background: linear-gradient(90deg, transparent, var(--cl-gold-dim), var(--cl-gold-bright), var(--cl-gold-dim), transparent);
    pointer-events: none
}

.custom-login-content:after {
    content: '';
    position: absolute;
    inset: 8px;
    border: 1px solid rgba(168, 132, 56, .12);
    border-radius: 10px;
    pointer-events: none
}

.custom-close {
