    background: hsla(0, 0%, 100%, .1);
    flex-shrink: 0;
    height: 20px;
    margin: 0 6px;
    width: 1px
}

.halim-controls-divider--group {
    margin: 0 8px
}

.halim-controls-divider--after-nav {
    display: none
}

@media (min-width:1100px) {
    .halim-controls-divider--after-nav {
        display: block
    }
}

.halim-control-btn {
    align-items: center;
    background: transparent;
    border: none;
    border-radius: 6px;
    box-sizing: border-box;
    color: hsla(0, 0%, 100%, .88);
    cursor: pointer;
    display: inline-flex;
    flex-direction: column;
    flex-shrink: 0;
    font-size: 12px;
    font-size: clamp(11px, .8vw, 13px);
    font-weight: 400;
    gap: 3px;
    gap: clamp(2px, .35vw, 4px);
    justify-content: center;
    line-height: 1.1;
    min-height: 48px;
    min-height: clamp(44px, 4.4vw, 52px);
    min-width: 52px;
    min-width: clamp(48px, 4.8vw, 62px);
    opacity: .92;
    padding: clamp(4px, .45vw, 6px) clamp(6px, .8vw, 10px) clamp(3px, .35vw, 5px);
    text-align: center;
    transition: background .15s ease, color .15s ease, opacity .15s ease
}

.halim-control-btn:hover {
    background: hsla(0, 0%, 100%, .08);
    opacity: 1
}

.halim-control-btn:active {
    background: hsla(0, 0%, 100%, .12)
}

.halim-control-btn:focus-visible {
    outline: 2px solid rgba(var(--player-accent), .65);
    outline-offset: 2px
}

.halim-control-btn i {
    display: block;
    flex-shrink: 0;
    font-size: 17px;
    font-size: clamp(16px, 1.2vw, 19px);
    line-height: 1
}

.halim-ep-icon {
    background-position: 50%;
    background-repeat: no-repeat;
    background-size: contain;
    display: block;
    flex-shrink: 0;
    height: 17px;
    height: clamp(16px, 1.2vw, 19px);
    width: 17px;
    width: clamp(16px, 1.2vw, 19px)
}

.halim-ep-icon--prev {
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='512' height='512' viewBox='0 0 24 24'%3E%3Cpath fill='%23fff' d='M19.972 20.882a1 1 0 0 1-1.027-.05l-12-8a1 1 0 0 1 0-1.664l12-8A1 1 0 0 1 20.5 4v16a1 1 0 0 1-.528.882M18.5 5.869 9.3 12l9.2 6.131zM4.5 19a1 1 0 0 1-1-1V6a1 1 0 0 1 2 0v12a1 1 0 0 1-1 1'/%3E%3C/svg%3E")
}

.halim-ep-icon--next {
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='512' height='512' viewBox='0 0 24 24'%3E%3Cpath fill='%23fff' d='M4.028 20.882a1 1 0 0 0 1.027-.05l12-8a1 1 0 0 0 0-1.664l-12-8A1 1 0 0 0 3.5 4v16a1 1 0 0 0 .528.882M5.5 5.869 14.7 12l-9.2 6.131zM19.5 19a1 1 0 0 0 1-1V6a1 1 0 0 0-2 0v12a1 1 0 0 0 1 1'/%3E%3C/svg%3E")
}

.halim-control-btn>span:not(.toggle-basic):not(.halim-toggle-light-label):not(.halim-ep-icon) {
    display: block;
    font-size: 11px;
    font-size: clamp(10px, .75vw, 12px);
    line-height: 1.15;
    text-align: center;
    white-space: nowrap;
    width: 100%
}

.halim-control-btn.halim-toggle-light .halim-toggle-light-label {
    font-size: 11px;
    font-size: clamp(10px, .75vw, 12px);
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis
}

.halim-control-btn.halim-toggle-light.is-light-off i {
    color: #f2c66b
}

.halim-favorite-btn.active {
    opacity: 1
}

.halim-favorite-btn.active i,
.halim-favorite-btn:hover i {
    color: #ff6b6b
}

.halim-favorite-btn i {
    color: inherit;
    transition: color .2s ease
}

.toggle-basic-btn .auto-next-text,
.toggle-basic-btn .auto-skip-text {
    font-size: 13px
}

.halim-controls-more-btn.is-open {
    background: rgba(var(--player-accent), .22);
    color: #fff;
    opacity: 1
}

.halim-controls-bar-extra {
    display: none
}

.halim-controls-sheet-extra {
    display: flex
}

@media (min-width:1100px) {
    .halim-controls-bar-extra {
        display: inline-flex
    }
    .halim-controls-sheet-extra {
        display: none !important
    }
    .halim-controls-left {
        gap: 14px
    }
    .halim-control-btn {
        min-height: 50px;
