}

.halim-controls-more-wrap {
    display: inline-flex;
    flex-shrink: 0;
    position: relative
}

.halim-controls-more-sheet {
    align-items: flex-end;
    bottom: 0;
    display: none;
    left: 0;
    position: fixed;
    right: 0;
    top: 0;
    inset: 0;
    justify-content: center;
    pointer-events: none;
    z-index: 10050
}

.halim-controls-more-sheet.is-open {
    display: flex;
    pointer-events: auto
}

div#hh3d-root-wrapper.halim-controls-sheet-open {
    overflow: hidden
}

.halim-controls-more-backdrop {
    background: rgba(0, 0, 0, .55);
    bottom: 0;
    left: 0;
    position: absolute;
    right: 0;
    top: 0;
    inset: 0;
    opacity: 0;
    transition: opacity .22s ease
}

.halim-controls-more-sheet.is-open .halim-controls-more-backdrop {
    opacity: 1
}

.halim-controls-more-panel {
    background: #1e1e1e;
    border: 1px solid hsla(0, 0%, 100%, .08);
    border-radius: 14px 14px 0 0;
    box-shadow: 0 -8px 32px rgba(0, 0, 0, .45);
    margin: 0 auto;
    max-height: 360px;
    max-height: min(70vh, 360px);
    max-width: 420px;
    overflow: hidden;
    position: relative;
    transform: translateY(100%);
    transition: transform .26s cubic-bezier(.32, .72, 0, 1);
    width: 100%;
    width: min(100%, 420px);
    z-index: 1
}

.halim-controls-more-sheet.is-open .halim-controls-more-panel {
    transform: translateY(0)
}

.halim-controls-more-header {
    align-items: center;
    border-bottom: 1px solid hsla(0, 0%, 100%, .08);
    display: flex;
    gap: 12px;
    justify-content: space-between;
    padding: 14px 16px
}

.halim-controls-more-header h3 {
    color: #f1f1f1;
    font-size: 16px;
    font-weight: 600;
    margin: 0
}

.halim-controls-more-close {
    align-items: center;
    background: transparent;
    border: none;
    border-radius: 6px;
    color: hsla(0, 0%, 100%, .7);
    cursor: pointer;
    display: inline-flex;
    height: 32px;
    justify-content: center;
    padding: 0;
    transition: background .15s ease, color .15s ease;
    width: 32px
}

.halim-controls-more-close:hover {
    background: hsla(0, 0%, 100%, .08);
    color: #fff
}

.halim-controls-more-body {
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    padding: 6px 0 10px
}

.halim-controls-more-row {
    align-items: center;
    background: transparent;
    border: none;
    box-sizing: border-box;
    color: hsla(0, 0%, 100%, .92);
    cursor: pointer;
    display: flex;
    font-size: 15px;
    gap: 12px;
    min-height: 52px;
    padding: 10px 16px;
    text-align: left;
    transition: background .15s ease;
    width: 100%
}

.halim-controls-more-row:focus-visible,
.halim-controls-more-row:hover {
    background: hsla(0, 0%, 100%, .06);
    outline: none
}

.halim-controls-more-row-icon {
    align-items: center;
    color: hsla(0, 0%, 100%, .75);
    display: inline-flex;
    flex-shrink: 0;
    font-size: 16px;
    justify-content: center;
    width: 22px
}

.halim-controls-more-row-label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

.halim-controls-more-row-action {
    flex-shrink: 0;
    margin-left: auto
}

.halim-controls-more-row-chevron {
    color: hsla(0, 0%, 100%, .35);
    flex-shrink: 0;
    font-size: 12px;
    margin-left: auto
}

.halim-controls-more-row.toggle-basic-btn {
    gap: 12px
}

.halim-controls-more-row .toggle-basic {
    margin: 0 !important
}

.halim-controls-more-row.halim-toggle-light.is-light-off .halim-controls-more-row-icon {
    color: #f2c66b
}

@media (min-width:1100px) {
    #halim-player-wrapper .halim-player-controls {
        position: relative;
        z-index: 30
    }
    .halim-controls-more-sheet {
        align-items: stretch;
        bottom: auto;
        height: auto;
        left: auto;
        position: fixed;
        right: auto;
        top: auto;
        inset: auto;
        justify-content: flex-start;
        width: 300px;
        width: min(300px, calc(100vw - 24px));
        z-index: 10050
    }
    .halim-controls-more-sheet.is-open {
        display: block
    }
    .halim-controls-more-backdrop {
        display: none
    }
    div#hh3d-root-wrapper.halim-controls-sheet-open {
        overflow: auto
    }
    .halim-controls-more-panel {
        border-radius: 10px;
        box-shadow: 0 10px 32px rgba(0, 0, 0, .45), 0 0 0 1px hsla(0, 0%, 100%, .06);
        margin: 0;
        max-height: 360px;
        max-height: min(70vh, 360px);
        opacity: 0;
        transform: translateY(-6px);
        transition: transform .18s ease, opacity .18s ease;
        width: 100%
    }
    .halim-controls-more-sheet.is-open .halim-controls-more-panel {
        opacity: 1;
        transform: translateY(0)
    }
    .halim-controls-more-header {
        padding: 10px 14px
    }
    .halim-controls-more-header h3 {
        font-size: 14px
    }
}

@media (min-width:1200px) {
    #halim-player-wrapper .halim-player-controls {
        padding: 0 18px
    }
    .halim-controls-left {
        gap: 16px
