    .halim-control-btn {
        min-height: 52px;
        min-width: 62px;
        padding: 7px 12px 6px
    }
}

@media (max-width:900px) {
    .halim-controls-left {
        gap: 6px;
        justify-content: flex-start;
        scroll-snap-type: x proximity
    }
    .halim-control-btn {
        scroll-snap-align: start
    }
}

@media (max-width:480px) {
    #halim-player-wrapper .halim-player-controls {
        min-height: 50px;
        padding: 0 8px
    }
    .halim-controls-left {
        gap: 8px;
        justify-content: flex-start
    }
    .halim-control-btn {
        font-size: 11px;
        min-height: 44px;
        min-width: 52px;
        padding: 4px 6px 3px
    }
    .halim-control-btn i {
        font-size: 16px
    }
    .halim-ep-icon {
        height: 16px;
        width: 16px
    }
    .halim-control-btn>span:not(.toggle-basic):not(.halim-toggle-light-label):not(.halim-ep-icon) {
        font-size: 10px
    }
}

