    margin-bottom: 20px;
    text-align: center
}

.movie-rating-rating-options {
    display: grid;
    gap: 15px;
    grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
    margin-bottom: 30px
}

.movie-rating-rating-option {
    align-items: center;
    background-color: rgba(0, 0, 0, .3);
    border-radius: 16px;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 15px 10px;
