    animation: lds-ellipsis1-notify .6s infinite;
    left: 8px
}

.lds-ellipsis-notify div:nth-child(2) {
    animation: lds-ellipsis2-notify .6s infinite;
    left: 8px
}

.lds-ellipsis-notify div:nth-child(3) {
    animation: lds-ellipsis2-notify .6s infinite;
    left: 32px
}

.lds-ellipsis-notify div:nth-child(4) {
    animation: lds-ellipsis3-notify .6s infinite;
    left: 56px
}

