.wpd-comment-right[style*="--vip-bg-url"] {
    overflow: visible !important;
    position: relative
}

.wpd-comment-right[style*="--vip-bg-url"]:before {
    background-image: var(--vip-bg-url);
    background-position: 50%;
    background-repeat: no-repeat;
    background-size: cover;
    border: none !important;
    border-radius: inherit;
    bottom: 0;
    content: "";
    filter: blur(1px);
    left: 0 !important;
    margin: 0 !important;
    opacity: .45;
    overflow: hidden;
    position: absolute;
    right: 0;
    top: 0 !important;
    transform: none !important;
    z-index: 0
}

.wpd-comment-right[style*="--vip-bg-url"] .wpd-comment-header {
    background: transparent !important
}

.wpd-comment-right[style*="--vip-bg-url"]:after {
    background: rgba(0, 0, 0, .15);
    bottom: 0;
    content: "";
    left: 0;
    position: absolute;
    right: 0;
    top: 0;
    z-index: 1
}

.wpd-comment-right[style*="--vip-bg-url"]>* {
    position: relative;
    z-index: 2
}

.wpd-comment-right[style*="--vip-bg-url"] .wpd-tools-actions {
    background: #fff !important;
    z-index: 999 !important
}

#wpdcom .wpd-tools {
    display: inline-block;
    position: relative !important
}

#wpdcom .wpd-tools-actions {
    background: linear-gradient(135deg, #2c2f33, #23272a) !important;
    border: 1px solid hsla(0, 0%, 100%, .1) !important;
    border-radius: 8px !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, .4), 0 2px 8px rgba(0, 0, 0, .3) !important;
    left: 50% !important;
    min-width: 160px !important;
    opacity: 0;
    padding: 6px 4px !important;
    pointer-events: none;
    position: absolute !important;
    top: calc(100% + 8px) !important;
    transform: translateX(-50%);
    transform: translateX(-50%) translateY(-8px);
    transition: opacity .2s ease, visibility .2s ease, transform .2s ease !important;
    visibility: hidden;
    z-index: 9999 !important
}

#wpdcom .wpd-tools-actions:hover,
#wpdcom .wpd-tools:hover .wpd-tools-actions {
    display: flex !important;
    opacity: 1 !important;
    pointer-events: auto !important;
    transform: translateX(-50%) translateY(0) !important;
    visibility: visible !important
}

#wpdcom .wpd-tools-actions:before {
    border-bottom: 6px solid #2c2f33;
    border-left: 6px solid transparent;
    border-right: 6px solid transparent;
    content: "";
    filter: drop-shadow(0 -2px 4px rgba(0, 0, 0, .3));
    height: 0;
    left: 50%;
    position: absolute;
    top: -6px;
    transform: translateX(-50%);
    width: 0;
    z-index: 1
}

#wpdcom .wpd-tools-actions .wpd-cta-button {
    align-items: center;
    border-radius: 6px !important;
    color: #e4e6eb !important;
    cursor: pointer !important;
    display: flex !important;
    font-size: 13px !important;
    font-weight: 500 !important;
    gap: 10px;
    margin: 2px 0 !important;
    padding: 10px 14px !important;
    position: relative;
    transition: all .2s ease !important;
    white-space: nowrap
}

#wpdcom .wpd-tools-actions .wpd-cta-button:hover {
    background: hsla(0, 0%, 100%, .08) !important;
    color: #fff !important;
    transform: translateX(2px)
}

#wpdcom .wpd-tools-actions .wpd_editable_comment:before {
    color: #4a9eff;
    content: "\f044";
    font-family: Font Awesome\ 5 Free;
    font-size: 13px;
    font-weight: 900
}

#wpdcom .wpd-tools-actions .wpdiscuz-fem-delete-comment:before {
    color: #ff4757;
    content: "\f2ed";
    font-family: Font Awesome\ 5 Free;
    font-size: 13px;
    font-weight: 900
}

#wpdcom .wpd-tools-actions .wpdiscuz-private-comment-action:before {
    color: #ffa502;
    content: "\f023";
    font-family: Font Awesome\ 5 Free;
    font-size: 13px;
    font-weight: 900
}

#wpdcom .wpd-tools-actions .wpd_editable_comment:hover {
    background: rgba(74, 158, 255, .15) !important
}

#wpdcom .wpd-tools-actions .wpd_editable_comment:hover:before {
    color: #6eb5ff
}

#wpdcom .wpd-tools-actions .wpdiscuz-fem-delete-comment:hover {
    background: rgba(255, 71, 87, .15) !important
}

#wpdcom .wpd-tools-actions .wpdiscuz-fem-delete-comment:hover:before {
    color: #ff6b7a
}

#wpdcom .wpd-tools-actions .wpdiscuz-private-comment-action:hover {
    background: rgba(255, 165, 2, .15) !important
}

#wpdcom .wpd-tools-actions .wpdiscuz-private-comment-action:hover:before {
    color: #ffb733
}

#wpdcom .wpd-tools i {
    color: #999 !important;
    transition: transform .3s ease, color .2s ease !important
}

#wpdcom .wpd-tools:hover i {
    color: #4a9eff !important;
    transform: rotate(90deg)
}

@media (max-width:768px) {
    #wpdcom .wpd-tools-actions {
        left: auto !important;
        min-width: 180px !important;
        right: 0 !important;
        transform: none !important
    }
    #wpdcom .wpd-tools-actions:hover,
    #wpdcom .wpd-tools:hover .wpd-tools-actions {
        transform: translateY(0) !important
    }
    #wpdcom .wpd-tools-actions:before {
        left: auto;
        right: 12px;
        transform: none
    }
    #wpdcom .wpd-tools-actions .wpd-cta-button {
        font-size: 14px !important;
        gap: 12px;
        padding: 12px 16px !important
    }
    #wpdcom .wpd-tools-actions .wpd-cta-button:before {
        font-size: 14px
    }
}

