    z-index: 2
}

.info-hero:before,
.info-v2-ambient {
    bottom: 0;
    left: 0;
    position: absolute;
    right: 0;
    top: 0;
    inset: 0;
    pointer-events: none
}

.info-v2-ambient {
    border-radius: 0;
    -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 14%, #000 86%, transparent);
    mask-image: linear-gradient(180deg, transparent 0, #000 14%, #000 86%, transparent);
