    height: 100%;
    left: 0;
    max-width: none;
    object-fit: cover;
    object-position: center 40%;
    pointer-events: none;
    position: absolute;
    top: 0;
    transform: scale(1.08);
    transform-origin: center 40%;
    user-select: none;
    width: 100%;
