    opacity: .22;
    pointer-events: none;
    position: absolute;
    z-index: 1
}

.info-v2-ambient:before {
    background: linear-gradient(180deg, rgba(28, 28, 28, .35) 0, rgba(37, 37, 43, .08) 40%, rgba(37, 37, 43, .12) 70%, rgba(28, 28, 28, .4));
