.effect-solid {
    color: var(--custom-display-name-styles-main-color) !important
}

.effect-gradient {
    background: linear-gradient(to right, var(--custom-display-name-styles-gradient-start-color), var(--custom-display-name-styles-gradient-end-color), var(--custom-display-name-styles-gradient-start-color));
    background-clip: text;
    -webkit-background-clip: text;
    background-size: 200% auto;
    -webkit-text-fill-color: transparent;
    animation: customGradientAnimation 3s linear infinite;
    position: relative;
    z-index: 0
}

@keyframes customGradientAnimation {
    0% {
        background-position: 0
    }
    to {
        background-position: 200%
    }
}

.effect-neon {
    paint-order: stroke fill;
    -webkit-text-stroke-color: var(--custom-display-name-styles-neon-stroke-color);
    animation: neonFlickerAnimation 4s cubic-bezier(.24, .31, .36, .93) infinite;
    color: #fff !important;
    margin-inline-start: calc(-1px - .04em);
    margin-bottom: calc(-1px - .04em);
    padding-bottom: calc(1px + .04em);
    padding-inline-start: calc(1px + .04em);
    position: relative;
    z-index: 0
}

.effect-neon,
.neon-glow {
    -webkit-text-stroke-width: calc(1px + .04em)
}

.neon-glow {
    background: linear-gradient(to bottom left, var(--custom-display-name-styles-light-2-color) 0, var(--custom-display-name-styles-light-2-color) 6%, var(--custom-display-name-styles-main-color) 20%, var(--custom-display-name-styles-light-1-color) 50%, var(--custom-display-name-styles-light-2-color) 56%, var(--custom-display-name-styles-main-color) 70%, var(--custom-display-name-styles-light-1-color) 100%);
    background-clip: text;
    -webkit-background-clip: text;
    background-position: 100% 0;
    background-size: 200% 200%;
    -webkit-text-fill-color: transparent;
    color: var(--custom-display-name-styles-main-color);
    filter: blur(calc(1px + .12em));
    opacity: .8;
    -webkit-text-stroke-color: transparent;
    animation: neonGlowFlickerAnimation 1666ms linear infinite;
    inset: 0;
    perspective: 1px;
    pointer-events: none;
    position: absolute;
    z-index: -1
}

.effect-toon {
    --custom-toon-stroke-width: calc(1.6px + 0.04em);
    --custom-toon-margin: calc(var(--custom-toon-stroke-width)*-1);
    paint-order: stroke fill;
    position: relative;
    white-space: nowrap;
    -webkit-text-stroke-width: var(--custom-toon-stroke-width);
    -webkit-text-stroke-color: var(--custom-display-name-styles-toon-stroke-color);
    color: var(--custom-display-name-styles-toon-stroke-color) !important;
    font-variant-ligatures: none;
    margin-inline-start: var(--custom-toon-margin);
    margin-bottom: var(--custom-toon-margin);
    margin-inline-end: var(--custom-toon-margin);
    padding-bottom: var(--custom-toon-stroke-width);
    padding-inline-end: var(--custom-toon-stroke-width);
    padding-inline-start: var(--custom-toon-stroke-width);
    text-rendering: optimizeLegibility;
    transition: color 266ms cubic-bezier(.43, .21, .27, .78);
    unicode-bidi: isolate
}

@media (max-width:768px) {
    .effect-toon {
        --custom-toon-stroke-width: calc(1px + 0.02em)
    }
}

.effect-toon:before {
    background: linear-gradient(180deg, #fff 0, var(--custom-display-name-styles-light-2-color) 8%, var(--custom-display-name-styles-light-1-color) 15%, var(--custom-display-name-styles-main-color) 25%, var(--custom-display-name-styles-light-2-color) 45%, var(--custom-display-name-styles-main-color) 55%, #fff 75%, var(--custom-display-name-styles-light-2-color) 83%, var(--custom-display-name-styles-light-1-color) 90%, var(--custom-display-name-styles-main-color) 100%);
    background-clip: text;
    -webkit-background-clip: text;
    background-size: 100% 400%;
    content: attr(data-text);
    inset: 0;
    padding-inline: var(--custom-toon-stroke-width);
    padding-bottom: var(--custom-toon-margin);
    position: absolute;
    width: 100%;
    -webkit-text-fill-color: transparent;
    -webkit-text-stroke-width: 0;
    -webkit-text-stroke-color: transparent;
    animation: toonAnimation 4s cubic-bezier(.44, .29, .48, 1) infinite;
    pointer-events: none;
    transition: opacity 266ms cubic-bezier(.43, .21, .27, .78);
    unicode-bidi: isolate;
    will-change: background-position;
    word-break: keep-all
}

.effect-pop {
    --custom-pop-stroke-width: calc(0.8px + 0.02em);
