    font-variant-ligatures: none;
    margin-bottom: calc(var(--custom-pop-stroke-width)*-1 - var(--custom-pop-bottom-translate));
    margin-inline-end: calc(var(--custom-pop-stroke-width)*-1);
    margin-inline-start: calc(var(--custom-pop-stroke-width)*-1);
    padding-bottom: calc(var(--custom-pop-stroke-width) + var(--custom-pop-bottom-translate));
    padding-inline-end: var(--custom-pop-stroke-width);
    padding-inline-start: var(--custom-pop-stroke-width);
    text-rendering: optimizeLegibility;
    unicode-bidi: isolate
}

@media (max-width:768px) {
    .effect-pop:before {
        bottom: 0 !important;
        content: attr(data-text) !important;
        height: 100% !important;
        left: 0 !important;
        margin: 0 !important;
        padding: 0 !important;
        position: absolute !important;
        right: 0 !important;
        top: .13em !important;
        width: 100% !important;
        -webkit-text-stroke-width: 0 !important;
        animation: popAnimationMain 4s cubic-bezier(.44, .29, .48, 1) infinite;
        display: block !important;
        line-height: 1 !important;
        transform: none !important;
        vertical-align: baseline !important;
        will-change: auto !important
