@keyframes t8-label-gold-surge {
    0%,
    90%,
    to {
        box-shadow: 0 0 3px gold, 0 0 7px #fff8c0, 0 0 14px gold;
        transform: scale(1)
    }
    95% {
        box-shadow: 0 0 6px gold, 0 0 12px #fff8c0, 0 0 20px gold;
        transform: scale(1.03)
    }
}

@keyframes t8-label-void-breathe {
    0%,
    to {
        opacity: 1;
        transform: scale(1)
    }
    50% {
        opacity: .88;
        transform: scale(1.02)
    }
}

@keyframes t8-label-ice-float {
    0%,
    to {
        transform: translateY(0)
    }
    50% {
        transform: translateY(-1.5px)
    }
}

@keyframes t8-label-divine-burst {
    0%,
    80%,
    to {
        filter: brightness(1);
        transform: scale(1)
    }
    88% {
        filter: brightness(1.2);
        transform: scale(1.05)
    }
}

@keyframes t8-label-decay-pulse {
    0%,
    to {
        opacity: 1;
        transform: scale(1)
    }
    25% {
        opacity: .8;
        transform: scale(1.02)
    }
    60% {
        opacity: 1;
        transform: scale(1)
    }
}

@keyframes t8-label-lord-pulse {
    0%,
    to {
        transform: scale(1)
    }
    40% {
        transform: scale(1.04)
    }
    70% {
        transform: scale(1.02)
    }
}

@keyframes t8-glow-thai-at {
    0% {
        box-shadow: 0 0 3px gold, 0 0 7px #fff8c0, 0 0 14px gold
    }
    33% {
        box-shadow: 0 0 3px #fff8c0, 0 0 7px gold, 0 0 14px #fff8c0
    }
    66% {
        box-shadow: 0 0 5px #fc0, 0 0 9px #fff8c0, 0 0 16px gold
    }
    to {
        box-shadow: 0 0 3px gold, 0 0 7px #fff8c0, 0 0 14px gold
    }
}

@keyframes t8-glow-tram-nga {
    0% {
        box-shadow: 0 0 3px #8b5cf6, 0 0 7px #c4b5fd, 0 0 13px #4c1d95
    }
    33% {
        box-shadow: 0 0 3px #c4b5fd, 0 0 7px #4c1d95, 0 0 13px #8b5cf6
    }
    66% {
        box-shadow: 0 0 5px #4c1d95, 0 0 9px #8b5cf6, 0 0 15px #c4b5fd
    }
    to {
        box-shadow: 0 0 3px #8b5cf6, 0 0 7px #c4b5fd, 0 0 13px #4c1d95
    }
}

@keyframes t8-glow-vinh-hang {
    0% {
        box-shadow: 0 0 3px #00cfff, 0 0 7px #7fd8ef, 0 0 13px #e0f8ff
    }
    33% {
        box-shadow: 0 0 3px #7fd8ef, 0 0 7px #e0f8ff, 0 0 13px #00cfff
    }
    66% {
        box-shadow: 0 0 5px #e0f8ff, 0 0 9px #00cfff, 0 0 15px #7fd8ef
    }
    to {
        box-shadow: 0 0 3px #00cfff, 0 0 7px #7fd8ef, 0 0 13px #e0f8ff
    }
}

@keyframes t8-glow-chan-than {
    0% {
        box-shadow: 0 0 4px gold, 0 0 8px #fff, 0 0 14px gold
    }
    50% {
        box-shadow: 0 0 4px #fff, 0 0 8px gold, 0 0 14px #fff
    }
    to {
        box-shadow: 0 0 4px gold, 0 0 8px #fff, 0 0 14px gold
    }
}

@keyframes t8-glow-ngu-suy {
    0% {
        box-shadow: 0 0 3px #7a2ae2, 0 0 7px #c8a0ff, 0 0 12px #1a0050
    }
    33% {
        box-shadow: 0 0 3px #c8a0ff, 0 0 7px #1a0050, 0 0 12px #7a2ae2
    }
    66% {
        box-shadow: 0 0 5px #1a0050, 0 0 9px #7a2ae2, 0 0 14px #c8a0ff
    }
    to {
        box-shadow: 0 0 3px #7a2ae2, 0 0 7px #c8a0ff, 0 0 12px #1a0050
    }
}

@keyframes t8-glow-ban-bo {
    0% {
        box-shadow: 0 0 4px gold, 0 0 8px #6a0dad, 0 0 15px #1a0030
    }
    33% {
        box-shadow: 0 0 4px #6a0dad, 0 0 8px #1a0030, 0 0 15px gold
    }
    66% {
        box-shadow: 0 0 6px #1a0030, 0 0 10px gold, 0 0 17px #6a0dad
    }
    to {
        box-shadow: 0 0 4px gold, 0 0 8px #6a0dad, 0 0 15px #1a0030
    }
}

