}

@keyframes vctvGlow12 {
    0% {
        background-position: 0;
        filter: drop-shadow(0 0 3px rgba(255, 215, 0, .5))
    }
    50% {
        background-position: 100%;
        filter: drop-shadow(0 0 8px rgba(255, 215, 0, .95)) drop-shadow(0 0 14px rgba(196, 30, 58, .7)) brightness(1.08)
    }
    to {
        background-position: 200%;
        filter: drop-shadow(0 0 3px rgba(255, 215, 0, .5))
    }
}

.bang-hoi-mau-van-co-than-vuong {
    animation: vctvGlow12 3.5s ease-in-out infinite;
    background: linear-gradient(90deg, #2a0060, #7b2fbe, #b08000, #ffe060, #fffbe0, #ffe060, #b08000, #c41e3a, gold, #7b2fbe, #2a0060);
    -webkit-background-clip: text;
    background-clip: text;
    background-size: 400% 100%;
    color: transparent;
    font-family: UVN Hai Ba Trung, sans-serif;
    font-size: 14px !important;
    font-weight: 700;
    letter-spacing: 2px;
    text-shadow: 0 0 5px rgba(255, 215, 0, .55), 0 0 10px rgba(123, 47, 190, .4)
}

@keyframes thvcVoid12 {
    0% {
        background-position: 0;
        filter: hue-rotate(0deg) brightness(1.1)
    }
    50% {
        background-position: 200%;
        filter: hue-rotate(180deg) brightness(1.4) drop-shadow(0 0 9px rgba(0, 200, 255, .75))
    }
    to {
        background-position: 400%;
        filter: hue-rotate(1turn) brightness(1.1)
    }
}

.bang-hoi-mau-thai-hu-vo-cuc {
    animation: thvcVoid12 2.5s linear infinite;
    background: linear-gradient(90deg, #0f003a, #6a0dad, #05f, #0af, #0fc, #00ff7f, gold, #f60, #f08, #6a0dad, #0f003a);
    -webkit-background-clip: text;
    background-clip: text;
    background-size: 500% 100%;
    color: transparent;
    font-family: UVN Hai Ba Trung, sans-serif;
    font-size: 14px !important;
    font-weight: 700;
    letter-spacing: 2px;
    text-shadow: 0 0 5px rgba(0, 200, 255, .6), 0 0 10px rgba(106, 13, 173, .45)
}

@keyframes hmclFire12 {
    0% {
        background-position: 0;
        filter: drop-shadow(0 0 2px rgba(255, 69, 0, .5)) brightness(.95)
    }
    30% {
        background-position: 80%;
        filter: drop-shadow(0 0 9px rgba(255, 215, 0, .95)) brightness(1.22)
    }
    65% {
        filter: drop-shadow(0 0 7px rgba(255, 69, 0, .9)) drop-shadow(0 0 12px rgba(139, 0, 0, .6)) brightness(1.06)
    }
    to {
        background-position: 200%;
        filter: drop-shadow(0 0 2px rgba(255, 69, 0, .5)) brightness(.95)
    }
}

.bang-hoi-mau-hong-mong-chi-luc {
    animation: hmclFire12 2.8s ease-in-out infinite;
    background: linear-gradient(90deg, #1a0000, #8b0000, #c20, #ff4500, #ff8c00, gold, #fff8c0, gold, #ff8c00, #ff4500, #8b0000, #1a0000);
    -webkit-background-clip: text;
    background-clip: text;
    background-size: 400% 100%;
    color: transparent;
    font-family: UVN Hai Ba Trung, sans-serif;
    font-size: 14px !important;
    font-weight: 700;
    letter-spacing: 2px;
    text-shadow: 0 0 5px rgba(255, 90, 0, .65), 0 0 10px rgba(255, 200, 0, .35)
}

@keyframes customRainbow12 {
    0% {
        background-position: 0 50%
    }
    50% {
        background-position: 100% 50%
    }
    to {
        background-position: 0 50%
    }
}

.bang-hoi-mau-custom {
    animation: customRainbow12 4s ease infinite;
    background: linear-gradient(90deg, #ff0080, #ff8c00, #ffe000, #0f8, #00cfff, #8a2be2, #ff0080);
    -webkit-background-clip: text;
    background-clip: text;
    background-size: 300% 100%;
    color: transparent;
    font-family: UVN Hai Ba Trung, sans-serif;
    font-size: 12px !important;
    font-weight: 700;
