    width: 13px;
    height: 13px;
    flex-shrink: 0;
    margin-left: 3px;
    vertical-align: middle
}

.hh3d-widget-preview .hh3d-preview-comment-time {
    font-size: 11px;
    color: var(--hh3d-muted)
}

.hh3d-widget-preview .hh3d-preview-meta-sep {
    color: rgba(255, 255, 255, .18)
}

.hh3d-widget-preview .hh3d-preview-comments-footer {
    border-top: 1px solid var(--hh3d-border-row)
}

.hh3d-widget-preview .hh3d-preview-comments-extended {
    border-top: 1px solid var(--hh3d-border-row);
    background: rgba(0, 0, 0, .08)
}

.hh3d-widget-preview .hh3d-preview-comments-extended:not([hidden]) {
    animation: hh3d-preview-panel-reveal .28s ease-out
}

.hh3d-widget-preview .hh3d-preview-comments-extended-list {
    display: flex;
    flex-direction: column
}

@media (min-width:390px) and (max-width:767px) {
    .hh3d-widget-preview .hh3d-preview-trending-card {
        flex: 0 0 136px
    }
    .hh3d-widget-preview .hh3d-preview-skeleton-card {
        flex: 0 0 136px
    }
}

@media (min-width:430px) and (max-width:767px) {
    .hh3d-widget-preview .hh3d-preview-trending-card {
        flex: 0 0 144px
    }
    .hh3d-widget-preview .hh3d-preview-skeleton-card {
        flex: 0 0 144px
    }
}

@media (min-width:768px) {
    .hh3d-widget-preview .hh3d-preview-trending-carousel {
        display: grid;
        grid-template-columns: repeat(5, minmax(0, 1fr));
        gap: 14px;
        overflow: visible;
        scroll-snap-type: none;
        padding: 4px 20px 16px
    }
    .hh3d-widget-preview .hh3d-preview-trending-card {
        flex: unset;
        width: auto
    }
    .hh3d-widget-preview .hh3d-preview-poster-top {
        top: 8px;
        right: 8px
    }
    .hh3d-widget-preview .hh3d-preview-skeleton-card {
        flex: unset;
        width: auto
    }
    .hh3d-widget-preview .hh3d-preview-trending-extended-grid {
        display: grid;
        grid-template-columns: repeat(5, minmax(0, 1fr));
        gap: 12px;
        overflow: visible;
        scroll-snap-type: none;
        padding: 14px 20px 16px
    }
    .hh3d-widget-preview .hh3d-preview-trending-card.is-compact {
        flex: unset;
        width: auto
    }
    .hh3d-widget-preview .hh3d-preview-comment-poster-wrap,
    .hh3d-widget-preview .hh3d-preview-skeleton-poster.is-small {
        width: 56px;
        height: 84px
    }
    .hh3d-widget-preview .hh3d-preview-comments-list,
    .hh3d-widget-preview .hh3d-preview-comments-extended-list,
    .hh3d-widget-preview .hh3d-preview-skeleton-comments {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr))
    }
    .hh3d-widget-preview .hh3d-preview-comment-card:nth-child(odd),
    .hh3d-widget-preview .hh3d-preview-skeleton-comment:nth-child(odd) {
        border-right: 1px solid var(--hh3d-border-row)
    }
}

