.halim-trending-slider {
    display: block;
    margin: 0 auto;
    max-width: 1400px;
    padding: 5px;
    position: relative;
    width: 100%
}

.halim-trending-header-container {
    border-bottom: 1px solid #1e2732;
    margin-bottom: 1.5rem;
    position: relative;
    width: 100%
}

.halim-trending-header {
    background: linear-gradient(90deg, #ff8a00, #ff2070);
    -webkit-background-clip: text;
    background-clip: text;
    color: #fff0;
    display: inline-block;
    font-size: 1.8rem;
    font-weight: 700;
    margin-bottom: 0;
    padding-bottom: .5rem;
    position: relative;
    text-transform: uppercase
}

.halim-trending-header:after {
    background: linear-gradient(90deg, #ff8a00, #ff2070);
    bottom: 0;
    content: "";
    height: .5px;
    left: 0;
    position: absolute;
    width: 100%
}

.halim-trending-header i.halim-trending-icon {
    animation: pulse 1.5s infinite;
    color: #ff8a00;
    margin-right: 10px
}

@keyframes pulse {
    0% {
        transform: scale(1)
    }
    50% {
        transform: scale(1.2)
    }
    to {
        transform: scale(1)
    }
}

.halim-trending-container {
    display: block;
    overflow: hidden;
    position: relative;
    width: 100%
}

.halim-trending-nav-button {
    align-items: center;
    background: #1a1d24;
    border: none;
    color: #6c757d;
    cursor: pointer;
    display: flex;
    height: 100px;
    justify-content: center;
    opacity: .8;
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    transition: all .3s ease;
    width: 40px;
    z-index: 10
}

.halim-trending-nav-button:hover {
    color: #fff;
    opacity: 1
}

.halim-trending-prev-button {
    border-radius: 0 4px 4px 0;
    left: -40px
}

.halim-trending-next-button {
    border-radius: 4px 0 0 4px;
    right: -40px
}

@media (max-width:768px) {
    .halim-trending-nav-button {
        display: none
    }
}

.halim-trending-track {
    cursor: grab;
    display: flex;
    gap: 1.5rem;
    overflow-x: auto;
    padding-bottom: 1.5rem;
    scroll-behavior: smooth;
    scrollbar-width: none;
    width: 100%;
    -webkit-overflow-scrolling: touch;
    user-select: none;
    will-change: transform, scroll-position
}

.halim-trending-no-click {
    pointer-events: none
}

.halim-trending-track.grabbing {
    cursor: grabbing !important;
    user-select: none !important
}

.halim-trending-track::-webkit-scrollbar {
    display: none
}

.halim-trending-card {
    cursor: pointer;
    display: block;
    flex: 0 0 auto;
    margin-top: 0;
    position: relative;
    width: 224px
}

.halim-trending-link {
    color: inherit;
    display: block;
    text-decoration: none
}

.halim-trending-poster-container {
    aspect-ratio: 3/4;
    display: block;
    overflow: hidden;
    position: relative
}

