.halim-trending-poster-image {
    display: block;
    height: 100%;
    object-fit: cover;
    transition: transform .3s ease;
    width: 100%
}

.halim-trending-poster-mask {
    background-color: hsla(0, 0%, 100%, .05);
    bottom: 0;
    left: 0;
    position: absolute;
    right: 0;
    top: 0;
    transition: background-color .3s ease;
    z-index: 1
}

.halim-trending-poster-container.hover-active .halim-trending-poster-mask,
.halim-trending-poster-container:hover .halim-trending-poster-mask {
    background-color: rgba(255, 193, 7, .1)
}

.halim-trending-poster-container.hover-active .halim-trending-poster-image,
.halim-trending-poster-container:hover .halim-trending-poster-image {
    transform: scale(1.05)
}

.halim-trending-rating {
    align-items: center;
    background-color: rgba(0, 0, 0, .7);
    border-radius: 20px;
    bottom: 10px;
    display: flex;
    padding: 5px 10px;
    position: absolute;
    right: 10px;
    z-index: 3
}

.halim-trending-rating-value {
    color: #ffc107;
    font-size: 14px;
    font-weight: 700
}

.halim-trending-info {
    align-items: center;
    display: flex;
    height: 70px;
    margin-top: 1rem;
    overflow: hidden
}

.halim-trending-number {
    background: linear-gradient(39deg, #fecf59, #fff1cc);
    -webkit-background-clip: text !important;
    background-clip: text !important;
    font-size: 3.5em;
    font-style: italic;
    font-weight: 800;
    line-height: 1;
    -webkit-text-fill-color: transparent !important;
    align-items: center;
    color: #fff0;
    display: flex;
    flex-shrink: 0;
    justify-content: center;
    margin-right: .5rem;
    width: 60px
}

.halim-trending-details {
    display: flex;
    flex: 1;
    flex-direction: column;
    justify-content: center;
    overflow: hidden
}

.halim-trending-title-text {
    color: #fff;
    font-size: 1.4rem;
    font-weight: 700;
    margin-top: 0
}

.halim-trending-original-title,
.halim-trending-title-text {
    display: block;
    margin-bottom: .25rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

.halim-trending-original-title {
    color: #9ca3af;
    font-size: 1rem
}

@media (max-width:768px) {
    .halim-trending-header {
        font-size: 1.5rem
    }
    .halim-trending-card {
        width: 220px
    }
    .halim-trending-number {
        font-size: 3.5em;
        width: 45px
    }
    .halim-trending-title-text {
        font-size: 1.2rem
    }
    .halim-trending-original-title {
        font-size: 1rem
    }
    .halim-trending-info {
        height: 60px
    }
}

@media (max-width:480px) {
    .halim-trending-card {
        width: 180px
    }
    .halim-trending-number {
        font-size: 3.5em;
        width: 40px
    }
    .halim-trending-title-text {
        font-size: 1.2rem
    }
    .halim-trending-info {
        height: 50px
    }
}

@keyframes halim-trending-spin {
    to {
        transform: rotate(1turn)
    }
}

.halim-trending-poster-container:before {
    background: #2a2b31;
    content: "";
    inset: 0;
    opacity: 1;
    pointer-events: none;
    position: absolute;
    transition: opacity .35s ease;
    z-index: 0
}

.halim-trending-poster-container:after {
    animation: halim-trending-spin .65s linear infinite;
    border: 3px solid hsla(0, 0%, 100%, .12);
    border-radius: 50%;
    border-top-color: hsla(0, 0%, 100%, .62);
    content: "";
    height: 32px;
    left: 50%;
    margin: -16px 0 0 -16px;
    pointer-events: none;
    position: absolute;
    top: 50%;
    transition: opacity .35s ease;
    width: 32px;
    z-index: 4
}

.halim-trending-poster-container.halim-trending-poster-loaded:after,
.halim-trending-poster-container.halim-trending-poster-loaded:before {
    opacity: 0
}

.halim-trending-poster-container.halim-trending-poster-loaded:after {
    animation: none;
    visibility: hidden
}

.halim-trending-poster-container .halim-trending-poster-image {
    position: relative;
    z-index: 1
}

.halim-trending-poster-container .halim-trending-poster-mask {
    z-index: 2
}

.halim-trending-poster-container .halim-trending-rating {
    z-index: 5
}